INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.66.0',
  '2026-08-04',
  'Новая страница Finance: плановые траты с напоминаниями и долги',
  E'Появилась страница «Finance» — регулярные платежи и долги в одном месте.\n\nПлановые траты: сумма, валюта, дата следующего платежа и повтор (разово, ежемесячно, ежегодно, раз в N месяцев или дней). Для ЖКХ есть пометка «сумма примерная» — в списке она со знаком ≈, а при оплате подставляется среднее последних платежей. Кнопка «Оплатил» записывает платёж и двигает дату; если заплатили за несколько периодов вперёд, укажите сколько — дата сдвинется на них. Есть «пропустить платёж» и заморозка подписки.\n\nНапоминания приходят за столько дней, сколько указано у траты. Автоплатёж заранее не беспокоит, но на следующий день после даты бот спросит, списалось ли, — чтобы в приложении не копилась неправда.\n\nСверху сводка: к оплате в этом месяце и следующем, просрочено, сколько нам должны, сколько в среднем уходит в месяц. Долги — в обе стороны, с частичными возвратами: остаток и статус считаются по истории, остаток можно простить. Все суммы приводятся к базовой валюте. Кнопка с глазом прячет суммы, если на экран смотрит кто-то ещё.',
  E'Фазы 1-2 плана (фактические траты с деревом категорий, счета и цели «отложено на» — впереди). Миграция 0076: finance_plans, finance_payments, finance_debts, finance_debt_payments + 4 колонки в user_settings; деньги NUMERIC(14,2).\n\nБудущие платежи НЕ материализуются: хранится план и правило повтора, вхождения до конца следующего месяца раскладываются на лету (кап 40 на план — иначе ежедневные повторы дают сотни строк). Оплата за N периодов двигает дату на N x интервал; день прижимается к концу месяца (31-е). Разовый план после оплаты выключается, skip пишет платёж с нулевой суммой и флагом skipped.\n\nВалюты: сводка приводится к базовой на СЕРВЕРЕ, чтобы цифра в приложении и в уведомлении бота совпадала; в истории платежа курс фиксируется (rate_to_base) — без этого прошлые месяцы пересчитывались бы при каждом изменении курса. Получение курсов вынесено из httpapi/converter.go в общий пакет internal/rates (кэш час), converter переведён на него.\n\nВоркер internal/financenotify (тик 15 мин) шлёт напоминания в утренний час по часовому поясу пользователя (finance_tz_off приходит с клиента при открытии страницы), дедуп по notified_for / autopay_asked_for. Долги: paid/remaining и статус считаются по истории возвратов, а не хранятся полем — иначе разъедутся.\n\nПроверено: полный curl-сценарий (создание планов, оплата за 2 периода = +6 месяцев для повтора раз в 3 месяца, фактическая сумма вместо примерной, среднее для подстановки, пропуск, фиксация курса eur->amd в платеже, долги от open через partial к paid, прощение остатка, сводка с конвертацией) и страница в браузере (создание траты и оплата за 3 периода: 06.08 -> 06.11).'
);
-- +goose StatementEnd

